head.script:
// 테스트 설명, 유효성 값 설정
//  _1 : columnInfo 파라미터를 Column 인덱스(숫자)로 지정하는 분리 샘플 (_2 는 Column ID 지정)
scwin.tData = {
    "description" : "[gridView > M > setMaxLength]<br/>Body Column 정보를 사용하여 특정 Column 의 maxLength 속성을 설정합니다.",
    "validation" : [
        "Body Column 이 inputType='text','textarea','textImage','secret','autoComplete' 인 경우에 동작합니다.",
        "columnInfo(필수) 파라미터로 maxLength 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "maxLength(필수) 파라미터로 한 문자의 길이를 1 로 계산(다국어 포함)하여 Column 에 입력 가능한 최대 길이를 숫자로 설정할 수 있어야 합니다.",
        "setMaxLength() 메소드는 Column 단위로 적용되고, setCellMaxLength() 메소드는 'custom' Column 의 특정 Cell 에만 적용됩니다.",
        "setMaxLength() 메소드는 inputType 속성값 허용 목록에 'autoComplete' 를 포함하지만 getMaxLength() 메소드는 'autoComplete' 를 포함하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_opt !== 'undefined') {
        $p.data.remove("dlt_opt");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body Column 인덱스(숨김 포함) - 0:col1(text) / 1:col2(text, setColumnVisible(1,false) 로 숨김) / 2:col3(textarea) / 3:col4(textImage) / 4:col5(secret) / 5:col6(autoComplete) / 6:col7(calendar). 모든 Column 의 초기 maxLength 는 30.\n[절차] columnInfo 로 Column 인덱스를, maxLength 로 설정할 값을 선택한 뒤 (setMaxLength) 실행.\n[확인] 출력의 (적용 Column ID) 로 인덱스가 숨김 Column 을 포함해 세어졌는지 / Column maxLength 속성에 지정한 값이 반영되는지 / autoComplete(인덱스 5) 는 getMaxLength 반환값이 undefined 인 것이 정상 / 동작 대상이 아닌 calendar(인덱스 6) 는 maxLength 속성이 30 에서 변경되지 않는지 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (Body Column id 와 동일한 컬럼 구성)
    //  ※ 공통 createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성하므로 col7 까지를 위해 인라인 생성한다.
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col6" name="col6" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col7" name="col7" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    dlt_bind.setJSON([
        { "col1": "노트북", "col2": "숨김값1", "col3": "설명입니다1", "col4": "아이콘1", "col5": "1234", "col6": "서울특별시강남구역삼동", "col7": "20260201" },
        { "col1": "모니터", "col2": "숨김값2", "col3": "설명입니다2", "col4": "아이콘2", "col5": "5678", "col6": "부산광역시해운대구우동", "col7": "20260202" },
        { "col1": "키보드", "col2": "숨김값3", "col3": "설명입니다3", "col4": "아이콘3", "col5": "9012", "col6": "대구광역시수성구범어동", "col7": "20260203" },
        { "col1": "마우스", "col2": "숨김값4", "col3": "설명입니다4", "col4": "아이콘4", "col5": "3456", "col6": "인천광역시연수구송도동", "col7": "20260204" }
    ], false);

    // autoComplete Column(인덱스 5) itemset 용 옵션 DataList (label ref=oLabel, value ref=oCode)
    let strOpt = '';
    strOpt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_opt" baseNode="list" repeatNode="map">';
    strOpt += '<w2:columnInfo>';
    strOpt += '<w2:column id="oCode" name="oCode" dataType="text"></w2:column>';
    strOpt += '<w2:column id="oLabel" name="oLabel" dataType="text"></w2:column>';
    strOpt += '</w2:columnInfo>';
    strOpt += '<w2:data use="true"></w2:data>';
    strOpt += '</w2:dataList>';
    $p.data.create(strOpt);
    // ※ 아이템 값은 par_maxLength 최대 옵션(10)보다 긴 11 문자로 구성 -> autoComplete Column 에서도 절삭 결과를 관찰할 수 있다.
    dlt_opt.setJSON([
        { "oCode": "서울특별시강남구역삼동", "oLabel": "서울특별시강남구역삼동" },
        { "oCode": "부산광역시해운대구우동", "oLabel": "부산광역시해운대구우동" },
        { "oCode": "대구광역시수성구범어동", "oLabel": "대구광역시수성구범어동" },
        { "oCode": "인천광역시연수구송도동", "oLabel": "인천광역시연수구송도동" }
    ], false);

    let acItemset = '<w2:choices><w2:itemset nodeset="data:dlt_opt"><w2:label ref="oLabel"></w2:label><w2:value ref="oCode"></w2:value></w2:itemset></w2:choices>';

    // target 생성
    //  Body Column 을 인덱스 기준으로 구성한다. (모든 Column 의 초기 maxLength 는 30 -> setMaxLength 적용 전/후 비교용)
    //   인덱스 0 : col1  inputType="text"          (동작 대상)
    //   인덱스 1 : col2  inputType="text"          (★ setColumnVisible(1,false) 로 숨김 -> 인덱스는 1 을 유지)
    //   인덱스 2 : col3  inputType="textarea"      (동작 대상)
    //   인덱스 3 : col4  inputType="textImage"     (동작 대상)
    //   인덱스 4 : col5  inputType="secret"        (동작 대상)
    //   인덱스 5 : col6  inputType="autoComplete"  (동작 대상, 단 getMaxLength 는 미포함)
    //   인덱스 6 : col7  inputType="calendar"      (동작 대상 아님 -> 미동작, maxLength 30 유지)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:900px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="0 : col1 (text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="1 : col2 (text, 숨김)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="hcol3" value="2 : col3 (textarea)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="hcol4" value="3 : col4 (textImage)"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol5" value="4 : col5 (secret)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hcol6" value="5 : col6 (autoComplete)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol7" value="6 : col7 (calendar)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" inputType="text" maxLength="30" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" maxLength="30" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="130" inputType="textarea" maxLength="30" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="130" inputType="textImage" maxLength="30" viewType="icon" imageSrc="/cm/images/base/ico_grid_add.svg" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="110" inputType="secret" maxLength="30" id="col5" dataList="col5"></w2:column>';
    strTarget += '<w2:column width="180" inputType="autoComplete" maxLength="30" id="col6" dataList="col6">' + acItemset + '</w2:column>';
    strTarget += '<w2:column width="*" inputType="calendar" maxLength="30" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" id="col7" dataList="col7"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // ★ 두번째 Column(인덱스 1) 을 숨김 -> "숨겨진 Column 도 포함하여 인덱스가 설정" 검증용
    scwin.target1.setColumnVisible(1, false);
}



// setMaxLength 실행 : columnInfo 를 Column 인덱스(숫자)로 전달하여 해당 Column 의 maxLength 속성을 설정
//  설정 결과는 Column 에 반영된 maxLength 속성값과 짝 메소드 getMaxLength() 반환값으로 확인한다.
//  (적용 Column ID 를 함께 출력하여 숨겨진 Column 을 포함한 인덱스로 대상이 결정되는지 확인)
scwin.btn_setMaxLength_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let maxLength = par_maxLength.getValue();

    scwin.target1.setMaxLength(columnInfo, maxLength);

    let cellInfo = scwin.target1.getCellInfo(columnInfo);
    let applied = cellInfo.options.maxLength;
    let getResult = scwin.target1.getMaxLength(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setMaxLength(" + columnInfo + ", '" + maxLength + "')"
        + " -> 적용 Column ID : " + cellInfo.options.id
        + " (inputType " + cellInfo.options.inputType + ")"
        + " / Column maxLength 속성 : " + applied
        + " / getMaxLength(" + columnInfo + ") : " + getResult);
}
